<?php require __DIR__.'/layout.php';$rows=db()->query("SELECT * FROM people WHERE published=1 AND group_type='INTEGRANTE' ORDER BY sort_order,name")->fetchAll();site_header('Integrantes');?>
<main id="conteudo-principal" class="content-page"><header class="page-banner"><span>NOSSA FORMAÇÃO</span><h1>Integrantes</h1><p>Conheça os músicos que fazem parte da BAMAB.</p></header><div class="people-grid"><?php foreach($rows as $p):?><article class="person-card"><?php if($p['photo_path']):?><img src="<?=e($p['photo_path'])?>" alt="<?=e($p['name'])?>"><?php else:?><div class="photo-placeholder">♪</div><?php endif;?><div><h3><?=e($p['name'])?></h3><strong><?=e($p['role'])?></strong><p><?=e($p['biography'])?></p></div></article><?php endforeach;?></div><?php if(!$rows):?><div class="empty-public">Os integrantes e suas biografias serão cadastrados pelo Admin.</div><?php endif;?></main><?php site_footer();?>